// === Tab: mySketch ===
// Translated to p5.js fork: oggy  https://openprocessing.org/sketch/555063

const gridSize = 55;
const dotSpacing = 8;
const maxDistortion = 15;

let dots = [];
let ripples = []; // ✅ 儲存所有水波

let bgTop, bgBottom;      // 背景漸層
let dotColorInner, dotColorOuter; // 點的顏色漸層

function setup() {
  createCanvas(600, 600);
  noStroke();

  // 背景顏色（上深下淺）
  bgTop = color(5, 25, 60);
  bgBottom = color(20, 80, 140);

  // 點的顏色（位移小 → 大）
  dotColorInner = color(180, 220, 255); // 微亮
  dotColorOuter = color(90, 200, 255);  // 藍綠

  // center grid
  const offset = (width - gridSize * dotSpacing) / 2;

  // initialize dots
  for (let i = 0; i < gridSize; i++) {
    dots[i] = [];
    for (let j = 0; j < gridSize; j++) {
      dots[i][j] = new Dot(i * dotSpacing + offset, j * dotSpacing + offset);
    }
  }
}

function draw() {
  drawGradientBackground();

  // 更新所有水波
  for (let i = ripples.length - 1; i >= 0; i--) {
    ripples[i].update();
    if (ripples[i].isDead()) {
      ripples.splice(i, 1);
    }
  }

  // 用加法混色讓光暈感更明顯
  blendMode(ADD);

  // 更新 & 繪製點
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      dots[i][j].update(ripples);
    }
  }

  blendMode(BLEND);
}

// 滑鼠點一下，新增一個水波
function mousePressed() {
  ripples.push(new Ripple((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}

// -------------------- Ripple class：水波本體 --------------------
class Ripple {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.radius = 0;
    this.speed = 3;       // 擴散速度
    this.bandWidth = 30;  // 波紋「有效帶」的寬度
    this.maxRadius = 350; // 最遠擴散距離
  }

  update() {
    this.radius += this.speed;
  }

  isDead() {
    return this.radius > this.maxRadius;
  }
}

// -------------------- Dot class：每一個點 --------------------
class Dot {
  constructor(x, y) {
    this.originalPosition = createVector(x, y);
    this.position = this.originalPosition.copy();
  }

  update(ripples) {
    // 以原始位置為基準，每禎重算（像「水」暫時扭曲空間）
    let basePos = this.originalPosition.copy();
    let totalOffset = createVector(0, 0);

    // 看每一個水波對這個點造成多少位移
    for (let r of ripples) {
      let dir = p5.Vector.sub(basePos, r.pos);
      let dist = dir.mag();

      // 只在「波紋帶」附近有影響：距離約等於 r.radius
      let inner = r.radius - r.bandWidth;
      let outer = r.radius + r.bandWidth;

      if (dist > inner && dist < outer) {
        // 將 dist 映射到 0 ~ PI 之間，做 sin 波形
        let phase = map(dist, inner, outer, 0, PI);

        dir.normalize();
        // 位移量：隨著 sin 變化，看起來像水面上下起伏
        let amp = maxDistortion * sin(phase) * map(r.radius, 0, r.maxRadius, 1.0, 0.2);
        dir.mult(amp);

        totalOffset.add(dir);
      }
    }

    this.position = p5.Vector.add(basePos, totalOffset);

    // 位移大小用來決定顏色漸層
    let offsetMag = totalOffset.mag();
    let t = constrain(offsetMag / maxDistortion, 0, 1);
    let c = lerpColor(dotColorInner, dotColorOuter, t);

    stroke(c);
    strokeWeight(2);
    point(this.position.x, this.position.y);
  }
}

// -------------------- 畫背景漸層 --------------------
function drawGradientBackground() {
  for (let y = 0; y < height; y++) {
    var t = y / height;
    var c = lerpColor(bgTop, bgBottom, t);
    stroke(c);
    line(0, y, width, y);
  }
}

